import {academicChapters} from './academic.mjs';
// Authored bilingual explanations. Worked values and source versions are injected by build-bible.
export const chapters=[];
function add(id,group,en,th,summaryEn,summaryTh,bodyEn,bodyTh,sources,stepsEn,stepsTh,related=[]){chapters.push({id,group,title:{en,th},summary:{en:summaryEn,th:summaryTh},body:{en:bodyEn,th:bodyTh},sources,diagram:{en:stepsEn,th:stepsTh},related});}
add('start','start','Start with the question','เริ่มจากคำถามที่อยากตอบ','Three paths. Three different kinds of evidence.','สามเส้นทาง ใช้หลักฐานคนละแบบ',`A useful carbon number starts with a question, not a satellite layer. **What did my organization emit?** Collect activity records. **How much carbon is in this forest?** Examine biomass and forest extent. **How many credits can I claim?** Follow an eligible project methodology and the registry process.

Kabonna opens on the map. Choose a province or use **↖ Select an area**, then read the date and unit beside each number. For a project estimate, use Project → Calculate with your own dated measurements. The map never fills those measurements for you.

This bible is a reading tool: search in Thai or English, open a chapter, follow the diagram, then check its sources. You can share the chapter link and return to the workbench. No account is required.`, `ตัวเลขคาร์บอนที่มีประโยชน์เริ่มจากคำถาม **องค์กรของเราปล่อยเท่าไร?** ต้องมีบันทึกกิจกรรม **ป่านี้เก็บคาร์บอนเท่าไร?** ดูมวลชีวภาพกับขอบเขตป่า **จะขอเครดิตได้เท่าไร?** ต้องใช้ระเบียบวิธีที่เหมาะสมและผ่านกระบวนการทะเบียน

คาบอนนะเปิดที่แผนที่ เลือกจังหวัดหรือกด **↖ เลือกพื้นที่** แล้วอ่านปีและหน่วยข้างตัวเลข หากประเมินโครงการ ให้ไปที่ โครงการ → คำนวณ และใส่ผลวัดที่มีวันที่ของคุณเอง ตัวเลขแผนที่ไม่ถูกนำไปกรอกแทนข้อมูลแปลง

คู่มือนี้ค้นได้ทั้งไทยและอังกฤษ เลือกบท อ่านแผนภาพ แล้วเปิดแหล่งอ้างอิง ส่งลิงก์บทให้เพื่อนและกลับไปใช้เครื่องมือได้โดยไม่ต้องสมัครสมาชิก`,['protocol','method'],['Organization → activity records → footprint','Forest → dated biomass → stock / change','Credit claim → project evidence → registry'],['องค์กร → บันทึกกิจกรรม → ฟุตพริ้นท์','ป่า → มวลชีวภาพมีวันที่ → สต็อก / การเปลี่ยนแปลง','ขอเครดิต → หลักฐานโครงการ → ทะเบียน'],['footprint','forest-stock','credits','scientific-audit']);
add('number-passport','start','Every number needs a passport','ตัวเลขทุกตัวต้องมีที่มา','Unit, place, time, method, source and quality travel together.','หน่วย พื้นที่ เวลา วิธี แหล่งข้อมูล และคุณภาพต้องเดินทางไปด้วยกัน',`Before using a number, ask six questions: **what quantity, which unit, which boundary, which period, which source version, and what uncertainty?** A 2020 stock is not a 2024 emission. A national total is not a parcel observation. A missing value is not zero.

The landscape JSON export carries source versions, conversion factors and conservation checks. The assessment JSON carries original inputs, dates, boundary and unverified status. Keep these files alongside the original evidence. Rounding is for reading; calculations retain precision.

For a chart, inspect its denominator: a percentage of projects differs from a percentage of tonnes. A monthly fire share describes the selected historical dataset, not the probability of a fire tomorrow.`, `ก่อนนำตัวเลขไปใช้ ถามให้ครบว่า **วัดอะไร หน่วยอะไร ขอบเขตไหน ช่วงเวลาใด แหล่งข้อมูลรุ่นไหน และไม่แน่นอนแค่ไหน?** สต็อกปี 2020 ไม่ใช่การปล่อยปี 2024 ยอดประเทศไม่ใช่ผลวัดรายแปลง และข้อมูลที่ไม่มีไม่เท่ากับศูนย์

JSON ของแผนที่เก็บรุ่นข้อมูล ตัวคูณ และการตรวจยอดรวม ส่วน JSON ของการประเมินเก็บค่าที่ป้อน วันที่ ขอบเขต และสถานะยังไม่ทวนสอบ เก็บไฟล์เหล่านี้พร้อมหลักฐานต้นทาง การปัดเศษมีไว้ให้อ่านง่าย การคำนวณยังรักษาความละเอียด

อ่านตัวหารของกราฟด้วย สัดส่วนจำนวนโครงการต่างจากสัดส่วนตันคาร์บอน สัดส่วนไฟรายเดือนอธิบายข้อมูลย้อนหลัง ไม่ได้ทำนายโอกาสเกิดไฟพรุ่งนี้`,['manifest','code'],['Quantity + unit','Boundary + period','Source version + quality','Display → export → review'],['ปริมาณ + หน่วย','ขอบเขต + ช่วงเวลา','รุ่นข้อมูล + คุณภาพ','แสดงผล → ส่งออก → ตรวจสอบ'],['units','uncertainty','exports']);
add('units','start','Units without the traps','หน่วยที่อ่านแล้วไม่หลงทาง','Carbon, CO₂, CO₂e and concentration answer different questions.','คาร์บอน CO₂ CO₂e และความเข้มข้นตอบคนละคำถาม',`**1 Mg = 1 tonne = 1,000 kg.** One hectare is 10,000 m²; one rai is 1,600 m², so rai × 0.16 = hectares. Thai Buddhist year − 543 gives the Common Era year for the historical RFD series.

**t C × 44/12 = t CO₂** converts carbon mass to the mass of its carbon dioxide. It does not turn biomass directly into CO₂: biomass first needs its carbon fraction. **CO₂e** also depends on gas-specific global warming potentials (GWP) and their time horizon. State the GWP basis when combining gases.

**ppm** is atmospheric concentration; **gCO₂/kWh** is electricity intensity; **tCO₂e/year** is a rate; **tCO₂e** can be a stock or a period total. Do not convert ppm or aerosol optical depth into a province emission by multiplying by area.`, `**1 Mg = 1 ตัน = 1,000 กิโลกรัม** หนึ่งเฮกตาร์มี 10,000 ตร.ม. หนึ่งไร่มี 1,600 ตร.ม. จึงแปลงไร่เป็นเฮกตาร์ด้วย × 0.16 ชุดข้อมูลกรมป่าไม้ย้อนหลังแปลง พ.ศ. เป็น ค.ศ. ด้วย − 543

**t C × 44/12 = t CO₂** เปลี่ยนมวลคาร์บอนเป็นมวลคาร์บอนไดออกไซด์ แต่ยังใช้กับมวลชีวภาพตรง ๆ ไม่ได้ ต้องคูณสัดส่วนคาร์บอนก่อน **CO₂e** ของก๊าซอื่นต้องอาศัยค่า GWP และกรอบเวลา ระบุฐาน GWP ทุกครั้งที่รวมหลายก๊าซ

**ppm** คือความเข้มข้นในอากาศ **gCO₂/kWh** คือความเข้มการปล่อยของไฟฟ้า **tCO₂e/ปี** คืออัตรา ส่วน **tCO₂e** อาจเป็นสต็อกหรือยอดช่วงเวลา ห้ามคูณ ppm หรือ AOD ด้วยพื้นที่แล้วเรียกว่าการปล่อยของจังหวัด`,['protocol','manifest'],['Biomass × carbon fraction → C','C × 44/12 → CO₂','Other gases × declared GWP → CO₂e'],['มวลชีวภาพ × สัดส่วนคาร์บอน → C','C × 44/12 → CO₂','ก๊าซอื่น × GWP ที่ระบุ → CO₂e'],['forest-stock','footprint','atmosphere']);
add('footprint','footprint','Calculate an organizational footprint','คำนวณฟุตพริ้นท์องค์กร','Start with the bills, meters and records you can defend.','เริ่มจากบิล มิเตอร์ และบันทึกที่ตรวจสอบได้',`Choose the organization boundary and reporting year first. List emission sources, assign scopes, then collect activity data with units and evidence. For each source: **emissions = activity × matching emission factor**. If a factor is already in CO₂e, do not apply GWP again. If it reports individual gases, convert using the declared GWP set before summing.

Worked teaching example: 1,000 kWh × **illustrative** 0.50 kgCO₂e/kWh = 500 kgCO₂e = 0.50 tCO₂e. The factor is not a current Thai grid factor. A real inventory needs the factor applicable to the year, geography and accounting method, with its published version.

Sum compatible entries within the agreed inventory boundary, disclose exclusions and separate offsets. Kabonna currently calculates forest project estimates; it does **not** collect a complete organizational inventory or submit CFO registration.`, `กำหนดขอบเขตองค์กรและปีรายงานก่อน ทำรายการแหล่งปล่อย แบ่ง Scope แล้วเก็บข้อมูลกิจกรรมพร้อมหน่วยและหลักฐาน แต่ละรายการใช้ **การปล่อย = ปริมาณกิจกรรม × ค่าการปล่อยที่ตรงกัน** หากค่าการปล่อยเป็น CO₂e อยู่แล้ว อย่าคูณ GWP ซ้ำ หากแยกก๊าซ ให้แปลงด้วยชุด GWP ที่ระบุก่อนรวม

ตัวอย่างเพื่อเรียนรู้: 1,000 kWh × **ค่าสมมติ** 0.50 kgCO₂e/kWh = 500 kgCO₂e = 0.50 tCO₂e ค่านี้ไม่ใช่ค่าการปล่อยไฟฟ้าไทยปัจจุบัน การทำจริงต้องเลือกค่าที่ตรงปี ประเทศ และวิธีบัญชี พร้อมรุ่นเอกสาร

รวมเฉพาะรายการที่เข้ากันได้ภายในขอบเขตที่ตกลง ระบุรายการที่ยังไม่ครอบคลุม และแยกการชดเชยออก คาบอนนะรุ่นนี้คำนวณการประเมินโครงการป่าไม้ ยังไม่ได้เก็บบัญชีการปล่อยองค์กรครบถ้วนหรือยื่นขึ้นทะเบียน CFO`,['protocol','tgo-cfo','iso1'],['Boundary + year','Activity × matching factor','Gas / GWP check','Scope totals + evidence'],['ขอบเขต + ปี','กิจกรรม × ค่าการปล่อยที่ตรงกัน','ตรวจชนิดก๊าซ / GWP','ยอด Scope + หลักฐาน'],['scopes','factors','cfo-lite']);
add('scopes','footprint','Scope 1, 2 and 3','Scope 1, 2 และ 3','Classify the activity before calculating it.','จัดกลุ่มกิจกรรมก่อนคำนวณ',`**Scope 1:** direct emissions from owned or controlled sources, such as fuel combustion in controlled equipment or refrigerant leakage. **Scope 2:** emissions associated with purchased electricity, steam, heat or cooling. **Scope 3:** other value-chain emissions, such as purchased goods, transport or waste, according to the applicable category.

A rented asset is not classified by its name alone: the consolidation approach, control and lease arrangement matter. For electricity, distinguish location-based and market-based accounting where applicable; a renewable claim needs eligible contractual evidence, not a green photograph.

Make a source register: activity, owner, scope/category, quantity, unit, factor version, evidence and missing-data explanation. Review for duplicates before calculating totals.`, `**Scope 1:** การปล่อยตรงจากแหล่งที่องค์กรเป็นเจ้าของหรือควบคุม เช่น การเผาเชื้อเพลิงในอุปกรณ์ที่ควบคุมและสารทำความเย็นรั่ว **Scope 2:** การปล่อยที่เกี่ยวข้องกับไฟฟ้า ไอน้ำ ความร้อน หรือความเย็นที่ซื้อมา **Scope 3:** การปล่อยอื่นในห่วงโซ่คุณค่า เช่น สินค้าที่ซื้อ ขนส่ง หรือของเสีย ตามหมวดที่เกี่ยวข้อง

ทรัพย์สินเช่าจัด Scope จากชื่ออย่างเดียวไม่ได้ ต้องพิจารณาวิธีรวมองค์กร การควบคุม และสัญญา ไฟฟ้าต้องแยกวิธี location-based และ market-based เมื่อเกี่ยวข้อง การอ้างพลังงานหมุนเวียนต้องมีหลักฐานสัญญาที่เข้าเกณฑ์

ทำทะเบียนแหล่งปล่อย: กิจกรรม ผู้รับผิดชอบ Scope/หมวด ปริมาณ หน่วย รุ่นค่าการปล่อย หลักฐาน และเหตุผลของข้อมูลที่ขาด ตรวจรายการซ้ำก่อนรวมยอด`,['protocol','scope2','scope3'],['Controlled sources → Scope 1','Purchased energy → Scope 2','Other value-chain sources → Scope 3'],['แหล่งที่ควบคุม → Scope 1','พลังงานที่ซื้อ → Scope 2','แหล่งอื่นในห่วงโซ่ → Scope 3'],['footprint','factors']);
add('factors','footprint','Choose and version an emission factor','เลือกค่าการปล่อยและเก็บรุ่น','A precise multiplication can still use the wrong factor.','คูณถูกทุกหลักก็ผิดได้ หากเลือกค่าการปล่อยผิด',`Match the factor to the activity unit, fuel or process, geography, reporting year and accounting boundary. Record its source document, table, version, gases included and GWP basis. Check whether it includes upstream emissions or only combustion: the two boundaries are not interchangeable.

Convert units before multiplying. Litres cannot be multiplied by a kgCO₂e/kg factor without a defensible density conversion. Spend-based estimates need the currency and price-year basis. Missing records should trigger a disclosed estimate or a data request, not a silent zero.

Prefer authoritative applicable factors; TGO publishes CFO resources and platform/API documentation. Their existence does not mean this app is connected to a TGO factor API. No TGO emission-factor API integration is claimed here.`, `ค่าการปล่อยต้องตรงกับหน่วยกิจกรรม เชื้อเพลิงหรือกระบวนการ ประเทศ ปีรายงาน และขอบเขตบัญชี เก็บเอกสาร ตาราง รุ่น ก๊าซที่รวม และฐาน GWP ตรวจว่าครอบคลุมต้นน้ำหรือเฉพาะการเผาไหม้ เพราะใช้แทนกันไม่ได้

แปลงหน่วยก่อนคูณ ลิตรคูณค่า kgCO₂e/kg ไม่ได้หากไม่มีความหนาแน่นที่มีหลักฐาน การประมาณจากรายจ่ายต้องระบุสกุลเงินและปีราคา ข้อมูลขาดต้องแสดงว่าเป็นค่าประมาณหรือขอข้อมูลเพิ่ม ไม่ใช่เติมศูนย์เงียบ ๆ

ใช้ค่าทางการที่เหมาะกับงาน อบก. มีทรัพยากร CFO และเอกสารแพลตฟอร์ม/API แต่การมีเอกสารไม่ได้หมายความว่าคาบอนนะเชื่อมต่อ API ค่าการปล่อยของ อบก. แล้ว`,['tgo-cfo','protocol'],['Activity unit','Factor unit / year / boundary','Evidence + version','Multiply only after matching'],['หน่วยกิจกรรม','หน่วย / ปี / ขอบเขตของค่าการปล่อย','หลักฐาน + รุ่น','คูณเมื่อข้อมูลตรงกัน'],['footprint','number-passport']);
add('cfo-lite','footprint','What we learned from CFO Lite','สิ่งที่เรียนรู้จาก CFO Lite','An organization-first workflow; a separate job from a forest map.','เริ่มที่องค์กร ซึ่งเป็นคนละงานกับแผนที่ป่า',`On 2 October 2026 we inspected CFO Lite’s public web interface: organization creation/join prompts, login options, searchable history, year filters and “not offset / offset” status. Calculation screens require authentication and were not inspected. Its official TGO app-store description advertises guided Scope 1–3 assessment, reports and certificates, with Thai/English support.

The useful pattern is the continuity: **organization → reporting period → activity evidence → calculation → history → offset status**. A stronger implementation could explain factors beside each entry, flag missing records and show the evidence behind an offset. These are proposed improvements, not features verified in CFO Lite.

Kabonna is an independent forest workbench, not CFO Lite or a TGO-certified platform. Organizational accounting would require a separate inventory module. Neither a calculated footprint nor a bought credit automatically grants an official certificate.`, `วันที่ 2 ตุลาคม 2026 เราตรวจหน้าเว็บสาธารณะของ CFO Lite พบทางสร้าง/เข้าร่วมองค์กร ตัวเลือกเข้าสู่ระบบ ประวัติที่ค้นได้ ตัวกรองปี และสถานะ “ยังไม่ชดเชย / ชดเชยแล้ว” หน้าคำนวณต้องเข้าสู่ระบบ จึงยังไม่ได้ตรวจ รายละเอียดแอปทางการของ อบก. ระบุการประเมิน Scope 1–3 แบบนำทาง รายงาน ใบประกาศ และภาษาไทย/อังกฤษ

รูปแบบที่น่าเรียนรู้คือความต่อเนื่อง **องค์กร → รอบรายงาน → หลักฐานกิจกรรม → คำนวณ → ประวัติ → สถานะชดเชย** สิ่งที่เราอาจทำเพิ่มคืออธิบายค่าการปล่อยข้างรายการ เตือนหลักฐานที่ขาด และให้เห็นที่มาของการชดเชย ทั้งหมดนี้เป็นข้อเสนอ ไม่ใช่ฟีเจอร์ที่ตรวจพบใน CFO Lite

คาบอนนะเป็นเครื่องมือป่าไม้อิสระ ไม่ใช่ CFO Lite หรือแพลตฟอร์มที่ อบก. รับรอง งานองค์กรต้องมีโมดูลบัญชีแยก การคำนวณฟุตพริ้นท์หรือซื้อเครดิตอย่างเดียวไม่ได้ทำให้ได้รับใบประกาศทางการ`,['cfolite','cfo-store','tgo-cfo'],['Organization','Period + activity records','Footprint calculation','History + offset evidence'],['องค์กร','รอบรายงาน + บันทึกกิจกรรม','คำนวณฟุตพริ้นท์','ประวัติ + หลักฐานชดเชย'],['footprint','offsets','standards']);
add('forest-stock','forest','From forest biomass to carbon stock','จากมวลชีวภาพป่าสู่คาร์บอนสะสม','Follow the full conversion chain, not a magic multiplier.','ดูสายการคำนวณเต็ม ไม่ใช่ตัวคูณลึกลับ',`The map estimates dry aboveground biomass (AGB) within JAXA forest classes, using ESA CCI biomass density. Density × forest-covered pixel area gives tonnes of AGB. The general-tree convention then adds roots and converts biomass to carbon dioxide mass:

**Stock = AGB × (1 + R) × CF × 44/12**

Here R = 0.27 is root:shoot and CF = 0.47 is carbon fraction. With 100 t AGB, roots add 27 t biomass; 127 × 0.47 = 59.69 t C; × 44/12 = **218.8633 tCO₂e**. This is biomass stock only, excluding soil, litter and dead wood. It is not an amount removed this year and not an issued credit.

The national worked example below uses the exact deployed data. Keep its 2020 label. The national inventory comparison warns of systematic differences; a narrow random-error band does not remove that warning.`, `แผนที่ประมาณมวลชีวภาพแห้งเหนือดิน (AGB) ภายในชั้นป่าของ JAXA โดยใช้ความหนาแน่นจาก ESA CCI ความหนาแน่น × พื้นที่ป่าในพิกเซล ให้ตัน AGB จากนั้นเพิ่มรากและแปลงเป็นมวลคาร์บอนไดออกไซด์ตามค่าต้นไม้ทั่วไป

**สต็อก = AGB × (1 + R) × CF × 44/12**

R = 0.27 คืออัตรารากต่อส่วนเหนือดิน CF = 0.47 คือสัดส่วนคาร์บอน ถ้ามี AGB 100 ตัน จะเพิ่มราก 27 ตัน ได้ 127 × 0.47 = 59.69 t C แล้ว × 44/12 = **218.8633 tCO₂e** เป็นสต็อกในมวลชีวภาพ ไม่รวมดิน ซากพืช และไม้ตาย ไม่ใช่ยอดดูดซับปีนี้หรือเครดิตที่รับรองแล้ว

ตัวอย่างระดับประเทศด้านล่างใช้ข้อมูลรุ่นที่ระบบใช้อยู่จริง ต้องอ่านพร้อมป้ายปี 2020 ผลเทียบกับบัญชีสำรวจเตือนถึงความต่างเชิงระบบ ช่วงความคลาดเคลื่อนสุ่มที่แคบไม่ได้ลบคำเตือนนี้`,['cci','fnf','method','nfi','code'],['AGB: 100 t','Roots: × 1.27 → 127 t','Carbon: × 0.47 → 59.69 t C','CO₂: × 44/12 → 218.8633 t'],['AGB: 100 ตัน','รวมราก: × 1.27 → 127 ตัน','คาร์บอน: × 0.47 → 59.69 t C','CO₂: × 44/12 → 218.8633 ตัน'],['uncertainty','nfi','project-change']);
add('forest-flux','forest','Forest removals, emissions and net flux','การดูดซับ การปล่อย และสุทธิของป่า','The only landscape net comes from one GFW model.','ยอดสุทธิของภูมิทัศน์ใช้แบบจำลอง GFW ชุดเดียว',`GFW’s model reports gross removals, gross emissions and net flux over 2001–2025. Divide each period total by 25 to display an annual average. **Net = (emissions − removals) / 25**; negative means a net sink under that model.

This is a historical model average, not a live annual measurement. Province summaries are ingested. The GFW grid is not ingested in this deployment, so an arbitrary drawn area has no GFW flux number. Missing stays unavailable.

Do not add ODIAC fossil emissions or GFED fire to this net. The products have different years, spatial definitions and overlapping processes. An apparently comprehensive “province balance” made from those rows would hide double counting and mismatched periods.`, `แบบจำลอง GFW รายงานการดูดซับรวม การปล่อยรวม และสุทธิของช่วง 2001–2025 หารยอดแต่ละรายการด้วย 25 เพื่อแสดงค่าเฉลี่ยรายปี **สุทธิ = (การปล่อย − การดูดซับ) / 25** ค่าติดลบหมายถึงแหล่งดูดซับสุทธิภายใต้แบบจำลองนี้

เป็นค่าเฉลี่ยจากแบบจำลองย้อนหลัง ไม่ใช่การวัดสดรายปี ระบบมีข้อมูลสรุปจังหวัด แต่ยังไม่ได้โหลดกริด GFW จึงไม่มีค่าฟลักซ์สำหรับกรอบพื้นที่ที่วาดเอง ข้อมูลขาดแสดงว่าไม่มี

อย่านำการปล่อยฟอสซิล ODIAC หรือไฟ GFED มาบวกกับสุทธินี้ ชุดข้อมูลมีปี นิยามพื้นที่ และกระบวนการที่ทับซ้อนกัน การสร้าง “ดุลคาร์บอนจังหวัด” จากแถวเหล่านี้จะซ่อนการนับซ้ำและช่วงเวลาที่ไม่ตรงกัน`,['gfw','manifest','code'],['2001–2025 model totals','Emissions − removals','÷ 25 years','Negative = net sink'],['ยอดแบบจำลอง 2001–2025','การปล่อย − การดูดซับ','÷ 25 ปี','ติดลบ = ดูดซับสุทธิ'],['fire','fossil','number-passport']);
add('fossil','forest','Fossil emissions on the map','การปล่อยฟอสซิลบนแผนที่','ODIAC is a spatial inventory, not an SME’s electricity bill.','ODIAC เป็นบัญชีเชิงพื้นที่ ไม่ใช่บิลไฟของ SME',`ODIAC2025 supplies 2024 fossil CO₂ emissions spatially distributed using its inventory model. In the ledger, **tonnes C × 44/12 = tonnes CO₂/year**. Sum the covered share of cells for the selected area. The national calculation below uses the deployed total.

The original nominal resolution is 1 km; the web selection grid is 0.025° (about 2.8 km). A smaller selection is suppressed rather than presented as a fine parcel observation. The number covers the inventory’s fossil emission sources; it is not a complete organizational Scope 1–3 inventory.

Climate TRACE 2024 is an independent context cross-check. Agreement is useful; disagreement needs investigation of scope and methods. It is not averaged with ODIAC.`, `ODIAC2025 กระจายการปล่อย CO₂ ฟอสซิลปี 2024 ในเชิงพื้นที่ด้วยแบบจำลองบัญชี ในตารางใช้ **ตัน C × 44/12 = ตัน CO₂/ปี** รวมส่วนของเซลล์ที่อยู่ในพื้นที่เลือก ตัวอย่างประเทศด้านล่างมาจากยอดที่ระบบใช้งานจริง

ข้อมูลต้นทางมีความละเอียดนามบัญญัติ 1 กม. แต่กริดเลือกพื้นที่บนเว็บเป็น 0.025° หรือราว 2.8 กม. พื้นที่เล็กกว่านี้จะไม่แสดงยอด เพื่อไม่ให้ดูเหมือนผลวัดแปลงละเอียด ตัวเลขครอบคลุมแหล่งฟอสซิลตามบัญชี ไม่ใช่บัญชีองค์กร Scope 1–3 ครบถ้วน

Climate TRACE ปี 2024 เป็นข้อมูลเทียบอิสระ หากต่างกันต้องตรวจขอบเขตและวิธี ไม่ได้นำมาเฉลี่ยกับ ODIAC`,['odiac','climatetrace','manifest'],['2024 inventory: t C','Selected cell shares','× 44/12','t CO₂/year'],['บัญชี 2024: t C','ส่วนเซลล์ในพื้นที่เลือก','× 44/12','t CO₂/ปี'],['footprint','geometry']);
add('fire','forest','Fire totals and seasonal charts','ยอดไฟและกราฟตามฤดูกาล','Historical landscape fire is not the project’s deduction.','ไฟย้อนหลังทั้งภูมิทัศน์ไม่ใช่ค่าหักของโครงการ',`GFED5.1 describes landscape fire emissions. This deployment displays the 2013–2022 mean, with monthly and ecosystem-category context. The fire row is tCO₂/year; the monthly chart uses historical fire-carbon totals and their shares. Category shares use the same dataset denominator.

Its 0.25° cells are about 28 km. Small selections cannot support a local fire total and are suppressed. Satellite fire detections and aerosol pictures are separate observations, not replacements for GFED emission estimates.

The project workbench asks for a dated burned-area and canopy-death assessment under its selected methodology. It does not automatically deduct the map’s fire row. An unknown fire assessment blocks calculation.`, `GFED5.1 อธิบายการปล่อยจากไฟในภูมิทัศน์ ระบบแสดงค่าเฉลี่ย 2013–2022 พร้อมบริบทเดือนและประเภทระบบนิเวศ แถวไฟมีหน่วย tCO₂/ปี กราฟเดือนใช้ยอดคาร์บอนจากไฟย้อนหลังและสัดส่วน ส่วนประเภทพื้นที่ใช้ตัวหารจากชุดเดียวกัน

เซลล์ 0.25° กว้างราว 28 กม. พื้นที่เล็กไม่รองรับยอดไฟท้องถิ่นจึงไม่แสดง จุดความร้อนและภาพละอองลอยเป็นข้อสังเกตอีกแบบ ไม่ได้ใช้แทนค่าการปล่อย GFED

เครื่องมือโครงการถามพื้นที่เผาไหม้และการตายของเรือนยอดที่มีวันที่ตามระเบียบวิธี ไม่ได้หักแถวไฟของแผนที่อัตโนมัติ หากยังไม่รู้ผลประเมินไฟ ระบบจะหยุดคำนวณ`,['gfed','method','code'],['GFED historical fire','Mean / month / category','28 km scale check','Separate from project fire evidence'],['ไฟย้อนหลัง GFED','เฉลี่ย / เดือน / ประเภท','ตรวจสเกล 28 กม.','แยกจากหลักฐานไฟโครงการ'],['project-change','atmosphere']);
add('atmosphere','forest','Vegetation and aerosol: what they can tell us','พืชพรรณและละอองลอยบอกอะไรได้','Powerful context, but two layers cannot calculate everything.','เห็นบริบทได้ดี แต่สองชั้นข้อมูลคำนวณทุกอย่างไม่ได้',`Vegetation and radar forest layers help locate canopy and interpret change. Biomass needs a calibrated biomass product or suitable field model. Aerosol optical depth (AOD) describes light extinction by particles along an atmospheric column; it is not tonnes of CO₂ or stored carbon.

NASA GIBS layers in Kabonna show dated aerosol, carbon monoxide, column CO₂ and fire imagery. They do not supply numeric inputs to the calculator. Cloud, retrieval gaps, transport of smoke and the product’s spatial resolution affect interpretation.

Use layers to ask better questions: where should we inspect forest change, smoke or a fire? Then obtain the measurements and methodology needed to quantify emissions or biomass. A generative model can explain evidence; it cannot invent missing observations.`, `ชั้นพืชพรรณและเรดาร์ป่าช่วยระบุตำแหน่งเรือนยอดและอ่านการเปลี่ยนแปลง มวลชีวภาพต้องใช้ผลิตภัณฑ์ที่สอบเทียบหรือสมการภาคสนามที่เหมาะสม AOD อธิบายการลดทอนแสงจากอนุภาคตลอดคอลัมน์อากาศ ไม่ใช่ตัน CO₂ หรือคาร์บอนสะสม

ชั้น NASA GIBS ในคาบอนนะแสดงภาพละอองลอย CO คอลัมน์ CO₂ และไฟตามวันที่ ไม่ได้ป้อนตัวเลขให้เครื่องคำนวณ เมฆ ช่องว่างการตรวจวัด การเคลื่อนที่ของควัน และความละเอียดของผลิตภัณฑ์มีผลต่อการอ่านภาพ

ใช้ภาพตั้งคำถามว่า ควรไปตรวจป่า ควัน หรือไฟตรงไหน แล้วหาผลวัดกับระเบียบวิธีเพื่อหาปริมาณจริง โมเดลสร้างข้อความช่วยอธิบายหลักฐานได้ แต่สร้างผลสังเกตที่ขาดขึ้นมาแทนไม่ได้`,['gibs','fnf','cci'],['Vegetation → canopy context','Aerosol / CO → atmospheric context','Dated field / inventory evidence','Quantification with a suitable method'],['พืชพรรณ → บริบทเรือนยอด','ละอองลอย / CO → บริบทอากาศ','หลักฐานภาคสนาม / บัญชีมีวันที่','หาปริมาณด้วยวิธีที่เหมาะสม'],['forest-stock','fire','footprint']);
add('geometry','system','How a selected area is counted','ระบบนับพื้นที่ที่เลือกอย่างไร','Pixels, boundaries and resolution determine the estimate.','พิกเซล ขอบเขต และความละเอียดกำหนดค่าประมาณ',`Province totals are precomputed against administrative boundaries. Drawn rectangles use exact spherical overlap fractions of the 0.025° web cells. Imported polygons use 4 × 4 sub-samples per cell, counting points inside outer rings and outside holes. This is an approximation at the web-grid scale, not a new high-resolution satellite analysis.

A project boundary importer accepts WGS84 longitude/latitude GeoJSON; it checks shape validity and overlaps. Net project area counts union coverage rather than double-counting overlapping features. Boundaries and uploaded CSVs remain browser-local.

Map selections count Thai land only. Below the available grid scale, proportional cell shares cannot establish parcel precision. A boundary is also not proof of ownership, carbon rights or legal project eligibility.`, `ยอดจังหวัดคำนวณไว้ล่วงหน้ากับขอบเขตปกครอง กรอบสี่เหลี่ยมใช้สัดส่วนการทับซ้อนบนทรงกลมของเซลล์เว็บ 0.025° ส่วนรูปหลายเหลี่ยมใช้จุดตัวอย่าง 4 × 4 ต่อเซลล์ นับจุดในวงนอกและนอกช่องว่าง เป็นการประมาณตามกริดเว็บ ไม่ใช่ประมวลผลดาวเทียมความละเอียดสูงใหม่

ตัวนำเข้าโครงการรับ GeoJSON พิกัด WGS84 แบบลองจิจูด/ละติจูด ตรวจรูปทรงและการทับซ้อน พื้นที่สุทธินับส่วนรวมโดยไม่บวกพื้นที่ซ้อนซ้ำ ขอบเขตและ CSV ที่อัปโหลดยังอยู่ในเบราว์เซอร์ของผู้ใช้

แผนที่นับเฉพาะพื้นที่ไทย การแบ่งสัดส่วนเซลล์เล็กกว่าสเกลข้อมูลไม่ได้พิสูจน์ความละเอียดรายแปลง ขอบเขตก็ไม่ใช่หลักฐานกรรมสิทธิ์ สิทธิคาร์บอน หรือคุณสมบัติโครงการตามกฎหมาย`,['manifest','codab','code'],['Boundary','Cell overlap / polygon samples','Thai-land mask','Resolution check → estimate or unavailable'],['ขอบเขต','ทับซ้อนเซลล์ / จุดตัวอย่าง','หน้ากากพื้นที่ไทย','ตรวจสเกล → ประมาณหรือไม่มีข้อมูล'],['uncertainty','exports','project-change']);
add('uncertainty','forest','Read the uncertainty honestly','อ่านความไม่แน่นอนอย่างตรงไปตรงมา','A range measures selected errors, not all the ways a model can be wrong.','ช่วงค่าครอบคลุมความคลาดเคลื่อนบางอย่าง ไม่ใช่ทุกความผิดพลาด',`The stock band propagates ESA biomass standard deviations into three random-error scenarios. The optimistic floor assumes independent pixel errors. The central model groups correlated errors within 2 × 2 web cells (about 5.6 km); blocks are independent. The conservative ceiling assumes all errors are correlated.

A 95% half-width is **1.96 × SD × biomass-to-CO₂ factor**. Central SD is √Σ(block SD sums²). Lower bounds are clipped at zero. The manifest documents aggregate calibration assumptions and extrapolation beyond 50 km.

These bands exclude systematic map bias, root:shoot uncertainty and carbon-fraction uncertainty. The NFI comparison is a separate warning. Do not label the central interval a complete project uncertainty assessment. A representative plot design and methodology-specific uncertainty treatment are still needed.`, `ช่วงสต็อกส่งต่อส่วนเบี่ยงเบนมาตรฐานของมวลชีวภาพ ESA เป็นสามสถานการณ์ความคลาดเคลื่อนสุ่ม ขอบล่างแบบมองโลกดีถือว่าพิกเซลอิสระ แบบกลางรวมความสัมพันธ์ในบล็อก 2 × 2 เซลล์เว็บหรือราว 5.6 กม. แล้วถือว่าบล็อกอิสระ ขอบบนแบบระมัดระวังถือว่าทุกความคลาดเคลื่อนสัมพันธ์กัน

ครึ่งความกว้างช่วง 95% = **1.96 × SD × ตัวแปลงมวลชีวภาพเป็น CO₂** แบบกลางใช้ SD = √Σ(ผลรวม SD ในบล็อก²) ค่าต่ำสุดไม่ต่ำกว่าศูนย์ manifest บันทึกสมมติฐานสอบเทียบรวมและการขยายเกิน 50 กม.

ช่วงเหล่านี้ไม่รวมอคติแผนที่เชิงระบบ ความไม่แน่นอนของรากหรือสัดส่วนคาร์บอน การเทียบ NFI เป็นคำเตือนแยก ห้ามเรียกช่วงกลางว่าเป็นการประเมินความไม่แน่นอนโครงการครบถ้วน ยังต้องมีแบบสำรวจที่เป็นตัวแทนและวิธีจัดการความไม่แน่นอนตามระเบียบวิธี`,['cci','manifest','nfi','code'],['ESA pixel SD','Assume correlation structure','Propagate → 95% range','Systematic bias remains outside'],['SD ของพิกเซล ESA','สมมติรูปแบบความสัมพันธ์','ส่งต่อ → ช่วง 95%','อคติเชิงระบบยังอยู่นอกช่วง'],['nfi','forest-stock','trees']);
add('nfi','forest','Why we show the national inventory warning','ทำไมต้องแสดงคำเตือนจากการสำรวจป่า','A national reference comparison keeps the map in perspective.','การเทียบข้อมูลประเทศช่วยให้มองข้อจำกัดแผนที่',`Thailand’s FREL/FRL submission provides national inventory results with a 2017 reference year and plots measured during 2013–2018. Our same-reference-year map comparison reads about **1.823 times** the inventory’s mean AGB density. Forest definitions, areas, measurement years and allometric bias differ.

The published inventory stock and a hypothetical allometric sensitivity are shown in the local comparison file. These compare unmatched forest populations; neither identifies map bias or rescales a province or parcel. A national ratio is not a local correction factor.

When map and inventory disagree, investigate the forest definition and field design before choosing the larger value. This matters for a client: a credible estimate explains the disagreement instead of hiding it behind a confident total.`, `รายงาน FREL/FRL ของไทยมีผลสำรวจป่าระดับประเทศ อ้างอิงปี 2017 และวัดแปลงในช่วง 2013–2018 การเทียบแผนที่ปีอ้างอิงเดียวกันให้ความหนาแน่น AGB เฉลี่ยประมาณ **1.823 เท่า** ของการสำรวจ นิยามป่า พื้นที่ ปีวัด และอคติสมการต่างกัน

ไฟล์เทียบแสดงทั้งสต็อกที่เผยแพร่และกรณีความไวต่อสมการแบบสมมติ ประชากรป่าไม่ตรงกัน ยังระบุอคติแผนที่ไม่ได้ และไม่ใช้ปรับจังหวัดหรือแปลง อัตราส่วนระดับประเทศไม่ใช่ตัวแก้รายพื้นที่

เมื่อแผนที่ต่างจากการสำรวจ ให้ตรวจนิยามป่าและแบบสำรวจก่อนเลือกยอดที่มากกว่า สำหรับลูกค้า ค่าประมาณที่น่าเชื่อถือควรอธิบายความต่าง ไม่ซ่อนไว้หลังยอดรวมที่ดูมั่นใจ`,['nfi','cci','fnf'],['Inventory field evidence','Same-reference-year map','Compare definitions + density','Warning, not automatic correction'],['หลักฐานสำรวจภาคสนาม','แผนที่ปีอ้างอิงเดียวกัน','เทียบนิยาม + ความหนาแน่น','คำเตือน ไม่ใช่ปรับค่าอัตโนมัติ'],['uncertainty','forest-stock']);
add('project-change','forest','Calculate a monitoring-period estimate','คำนวณค่าประมาณช่วงติดตาม','Two dated measurements; explicit factors and deductions.','ผลวัดสองวันที่ พร้อมตัวคูณและค่าหักชัดเจน',`The implemented workbench uses **T-VER-S-METH-13-01 v2** and its tree-tool convention for the supported case. Supply an initial and a monitoring value for the same net boundary, their dates and source labels. Select AGB or already-converted CO₂ stock explicitly.

For AGB inputs, convert both with the selected R and CF. **Δ stock = monitoring − initial. Estimate = Δ stock − applicable project fire emissions.** The implementation carries leakage = 0 for this scoped method; this is not a universal rule for forest projects.

Fire emissions apply here when burned area exceeds 5% and canopy death is “yes”. Unknown canopy assessment blocks the result. The annual average divides the net by elapsed days / 365.25. Above 16,000 tCO₂e/year the tool flags a larger-project review; this screen is not a determination of eligibility. All outputs remain unverified estimates and issued credits remain null.`, `เครื่องมือใช้ **T-VER-S-METH-13-01 v2** กับค่าตามเครื่องมือคำนวณต้นไม้สำหรับกรณีที่รองรับ ใส่ค่าเริ่มต้นและค่าติดตามของขอบเขตสุทธิเดียวกัน พร้อมวันที่และแหล่งข้อมูล เลือกชัดเจนว่าเป็น AGB หรือสต็อก CO₂ ที่แปลงแล้ว

หากป้อน AGB จะแปลงทั้งสองค่าด้วย R และ CF ที่เลือก **Δ สต็อก = ค่าติดตาม − ค่าเริ่มต้น ค่าประมาณ = Δ สต็อก − การปล่อยไฟโครงการที่เข้าเกณฑ์** โค้ดใช้ leakage = 0 สำหรับขอบเขตระเบียบวิธีนี้ ไม่ใช่กฎทั่วไปของโครงการป่าทุกประเภท

รุ่นนี้ใช้ค่าการปล่อยไฟเมื่อพื้นที่เผาเกิน 5% และเรือนยอดตาย “ใช่” หากยังไม่รู้จะคำนวณไม่ได้ ค่าเฉลี่ยรายปีหารยอดสุทธิด้วยจำนวนวัน / 365.25 หากเกิน 16,000 tCO₂e/ปี จะเตือนให้ตรวจโครงการขนาดใหญ่ ไม่ใช่ตัดสินคุณสมบัติ ทุกผลยังเป็นค่าประมาณไม่ทวนสอบ และเครดิตรับรองยังเป็น null`,['method','code'],['Same boundary + two dates','Convert both stocks','Monitoring − initial − applicable fire','Unverified estimate → independent review'],['ขอบเขตเดียวกัน + สองวันที่','แปลงสต็อกทั้งคู่','ติดตาม − เริ่มต้น − ไฟที่เข้าเกณฑ์','ค่าประมาณไม่ทวนสอบ → ตรวจอิสระ'],['trees','credits','exports']);
add('trees','forest','From tree measurements to a project estimate','จากการวัดต้นไม้สู่ค่าประมาณโครงการ','The equation must fit the forest and the sampling design.','สมการต้องตรงชนิดป่าและแบบสำรวจ',`The supported allometry is Ogawa et al. (1965), for mixed deciduous / dry dipterocarp trees, as listed in the TGO tree-tool appendix. DBH is in cm and height in m; supported trees have DBH ≥ 4.5 cm. Let x = DBH² × height.

Stem kg = 0.0396x^0.933; branch kg = 0.00349x^1.030; leaves kg = 1 / [28/(stem + branch) + 0.025]. **AGB tonnes = (stem + branch + leaves)/1,000.** It is not a universal equation for all Thai forests.

The plot importer sums trees, counts each plot’s area once, and expands **surveyed AGB / surveyed hectares × project hectares**. It rejects duplicate tree IDs within a plot and inconsistent plot areas. Expansion assumes a representative sample in one homogeneous stratum. It does not calculate statistical sampling uncertainty or fill unsurveyed strata.`, `สมการที่รองรับคือ Ogawa และคณะ (1965) สำหรับป่าเบญจพรรณ/ป่าเต็งรังตามภาคผนวกเครื่องมือต้นไม้ของ อบก. DBH ใช้ซม. ความสูงใช้ม. รองรับต้นที่ DBH ≥ 4.5 ซม. กำหนด x = DBH² × ความสูง

ลำต้นกก. = 0.0396x^0.933 กิ่งกก. = 0.00349x^1.030 ใบกก. = 1 / [28/(ลำต้น + กิ่ง) + 0.025] **AGB ตัน = (ลำต้น + กิ่ง + ใบ)/1,000** ไม่ใช่สมการสากลของป่าไทยทุกชนิด

ตัวนำเข้าแปลงรวมต้นไม้ นับพื้นที่แต่ละแปลงครั้งเดียว และขยายด้วย **AGB ที่สำรวจ / เฮกตาร์ที่สำรวจ × เฮกตาร์โครงการ** ปฏิเสธรหัสต้นซ้ำในแปลงและพื้นที่แปลงไม่ตรงกัน สมมติว่าเป็นตัวอย่างที่เป็นตัวแทนในชั้นป่าเดียว ไม่ได้คำนวณความไม่แน่นอนทางสถิติหรือเติมข้อมูลชั้นป่าที่ไม่ได้สำรวจ`,['method','code'],['DBH cm + height m','Suitable tree equation → kg','Plot sum / surveyed ha','× project ha → AGB tonnes'],['DBH ซม. + สูง ม.','สมการที่เหมาะ → กก.','ยอดแปลง / เฮกตาร์สำรวจ','× เฮกตาร์โครงการ → AGB ตัน'],['project-change','uncertainty']);
add('credits','credits','When an estimate becomes a credit','ค่าประมาณจะเป็นเครดิตเมื่อไร','A calculator cannot skip the project and registry gates.','เครื่องคำนวณข้ามขั้นโครงการและทะเบียนไม่ได้',`A stock estimate describes carbon held in biomass. A monitoring estimate describes change under stated assumptions. An **issued credit** is a registry record following the applicable program’s project, monitoring and assurance requirements. These are three different things.

Before a project claim, check eligible activities, land and carbon rights, baseline/additionality where required, monitoring, uncertainty, deductions, leakage and reversal rules. Requirements vary by methodology and program. Independent validation/verification and the issuing authority’s decision cannot be replaced by an attractive map.

Kabonna exports evidence for review and shows published registry records as context. It does not issue, transfer or retire credits. Never multiply a stock number by a market price and present it as realizable project revenue.`, `สต็อกอธิบายคาร์บอนที่อยู่ในมวลชีวภาพ ค่าประมาณช่วงติดตามอธิบายการเปลี่ยนแปลงภายใต้สมมติฐาน ส่วน **เครดิตที่รับรองแล้ว** เป็นรายการทะเบียนหลังผ่านข้อกำหนดโครงการ การติดตาม และการตรวจรับรองของโปรแกรม เป็นคนละสิ่งกัน

ก่อนอ้างเครดิต ต้องตรวจประเภทกิจกรรม สิทธิที่ดินและคาร์บอน baseline/additionality เมื่อกำหนด การติดตาม ความไม่แน่นอน ค่าหัก leakage และกติกาการย้อนกลับ ข้อกำหนดต่างกันตามระเบียบวิธีและโปรแกรม แผนที่สวยไม่แทนการตรวจอิสระหรือคำตัดสินของหน่วยออกเครดิต

คาบอนนะส่งออกหลักฐานเพื่อให้ตรวจ และแสดงทะเบียนเผยแพร่เป็นบริบท ไม่ออก โอน หรือยกเลิกเครดิต ห้ามเอาสต็อกคูณราคาตลาดแล้วเสนอเป็นรายได้ที่โครงการจะได้รับจริง`,['method','tver','iso2','iso3'],['Estimate + evidence','Eligibility / method / monitoring','Independent assurance + authority decision','Registry issuance'],['ค่าประมาณ + หลักฐาน','คุณสมบัติ / วิธี / ติดตาม','ตรวจอิสระ + หน่วยงานตัดสิน','ออกเครดิตในทะเบียน'],['registry','offsets','standards']);
add('registry','credits','Read the Thai project and credit ledger','อ่านทะเบียนโครงการและเครดิตไทย','Expected tonnes and issued tonnes use different clocks.','ตันคาดการณ์กับตันรับรองใช้เวลาคนละแบบ',`The local TGO FOR & AGR snapshot is dated **28 September 2026**. Project expected reductions are annual forecasts (tCO₂e/year). Issued credits are recorded amounts from issuance events, not annual forecasts. A registered project can have no issuance yet.

Counts use unique project keys. A multi-province project can appear in several provincial lists; its full tonnes are kept in the multi-province bucket for national conservation, not assigned in full to each province. Unlocated projects remain unlocated. A shared province is a screening connection, not a confirmed parcel overlap.

Portfolio charts count projects or sum the labelled tonnes. Issuance timelines follow issuance dates; developer and family charts use the published classification. Check the record link for detail. This is a dated snapshot, not a live registry connection.`, `ข้อมูล TGO FOR & AGR ในระบบเป็น snapshot **28 กันยายน 2026** ยอดลดที่คาดเป็นรายปี (tCO₂e/ปี) ส่วนเครดิตรับรองเป็นยอดจากเหตุการณ์ออกเครดิต ไม่ใช่ยอดคาดการณ์รายปี โครงการขึ้นทะเบียนแล้วอาจยังไม่มีการออกเครดิต

นับด้วยรหัสโครงการไม่ซ้ำ โครงการหลายจังหวัดอาจอยู่ในหลายรายชื่อจังหวัด แต่ตันทั้งหมดอยู่ในกลุ่มหลายจังหวัดเพื่อรักษายอดประเทศ ไม่แจกยอดเต็มให้ทุกจังหวัด โครงการไม่มีพิกัดยังอยู่กลุ่มไม่ทราบที่ตั้ง จังหวัดเดียวกันเป็นเพียงความเชื่อมโยงสำหรับคัดกรอง ไม่ใช่ยืนยันว่าแปลงทับซ้อน

กราฟพอร์ตนับโครงการหรือรวมตันตามป้าย กราฟเวลาตามวันที่ออกเครดิต กราฟผู้พัฒนาและประเภทตามข้อมูลเผยแพร่ เปิดลิงก์รายการเพื่อดูรายละเอียด เป็นข้อมูลตามวันที่ ไม่ใช่เชื่อมทะเบียนสด`,['registry-data','tver'],['Unique project keys','Annual expected ≠ issued amount','Single / multi / unlocated buckets','National conservation check'],['รหัสโครงการไม่ซ้ำ','คาดรายปี ≠ ยอดออกเครดิต','จังหวัดเดียว / หลายจังหวัด / ไม่ทราบ','ตรวจยอดรวมประเทศ'],['credits','markets']);
add('offsets','credits','Offsets need retirement evidence','ชดเชยต้องมีหลักฐานยกเลิกเครดิต','Buying a credit is not the same as using it for a claim.','ซื้อเครดิตไม่เท่ากับนำไปอ้างการชดเชยแล้ว',`First calculate and report the inventory under its boundary. Reduce emissions through real operational changes. If making an offset claim, identify the credit program, project, vintage, serials, quantity and beneficiary; check eligibility for the claim and obtain retirement/cancellation evidence in the appropriate registry.

Keep gross inventory emissions and the offset claim separate. A purchase receipt alone does not establish that units were retired or that another entity cannot claim them. Explain residual emissions and the rules of any label or certificate you seek.

Kabonna has no purchase, retirement or certificate-issuance integration. CFO Lite’s published description advertises offset-related features; the authenticated transaction workflow was not reviewed.`, `คำนวณและรายงานบัญชีการปล่อยตามขอบเขตก่อน ลดการปล่อยด้วยการปรับการดำเนินงานจริง หากอ้างชดเชย ให้ระบุโปรแกรม โครงการ vintage หมายเลขหน่วย จำนวน และผู้รับประโยชน์ ตรวจว่าใช้กับคำกล่าวอ้างนั้นได้ และมีหลักฐานยกเลิก/retire ในทะเบียนที่เกี่ยวข้อง

แยกการปล่อยรวมจากคำกล่าวอ้างการชดเชย ใบซื้ออย่างเดียวไม่ได้พิสูจน์ว่าหน่วยถูกยกเลิกหรือไม่มีคนอื่นอ้างซ้ำ อธิบายการปล่อยที่เหลือและกติกาของฉลากหรือใบประกาศที่ขอ

คาบอนนะไม่ได้เชื่อมซื้อ ยกเลิก หรือออกใบประกาศ รายละเอียดเผยแพร่ของ CFO Lite ระบุฟีเจอร์เกี่ยวกับชดเชย แต่เราไม่ได้ตรวจธุรกรรมหลังเข้าสู่ระบบ`,['tver','protocol','cfo-store'],['Gross footprint','Reduce operations','Eligible credit + serials','Retirement evidence + distinct claim'],['ฟุตพริ้นท์รวม','ลดจากการดำเนินงาน','เครดิตที่เข้าเกณฑ์ + หมายเลข','หลักฐาน retire + แยกคำกล่าวอ้าง'],['credits','footprint','registry']);
add('markets','credits','Carbon prices are not interchangeable','ราคาคาร์บอนใช้แทนกันไม่ได้','Read the instrument, currency and unit before comparing.','อ่านประเภท สกุลเงิน และหน่วยก่อนเทียบ',`The world rail separates instruments. RGGI auction prices are **USD per short ton** of allowance; EU CBAM reference prices are **EUR per tCO₂**; Thai T-VER reported transactions concern credits. An allowance, a border-adjustment certificate reference and a voluntary credit are not equivalent assets.

A reported volume-weighted price is **sum of transaction value / sum of traded volume** for its stated reporting period. It is not the latest executable quote or a guaranteed price for your project. Zero volume has no average price.

The World Bank’s 2026 report describes 87 carbon-pricing policies, over US$107 billion public revenue in 2025 and an 8% rise in credit issuance from 2024 to 2025. These are dated global context, not a live trading feed.`, `แถบโลกแยกประเภทตราสาร ราคา RGGI เป็น **USD ต่อ short ton** ของ allowance ราคาอ้างอิง EU CBAM เป็น **EUR ต่อ tCO₂** ส่วนธุรกรรม T-VER ไทยเกี่ยวกับเครดิต allowance ราคาอ้างอิงใบรับรองชายแดน และเครดิตภาคสมัครใจไม่ใช่สินทรัพย์ชนิดเดียวกัน

ราคาเฉลี่ยถ่วงน้ำหนักปริมาณที่รายงาน = **ผลรวมมูลค่าธุรกรรม / ผลรวมปริมาณซื้อขาย** ของรอบที่ระบุ ไม่ใช่ราคาเสนอซื้อขายล่าสุดหรือราคาที่รับประกันให้โครงการคุณ หากปริมาณเป็นศูนย์จะไม่มีราคาเฉลี่ย

รายงาน World Bank ปี 2026 กล่าวถึงนโยบายราคาคาร์บอน 87 นโยบาย รายได้รัฐปี 2025 เกิน 107 พันล้าน USD และการออกเครดิตเพิ่ม 8% จาก 2024 เป็น 2025 เป็นบริบทโลกมีวันที่ ไม่ใช่ฟีดซื้อขายสด`,['worldbank','rggi','cbam','registry-data'],['Instrument','Currency + tonne basis','Period + volume','Compare only compatible prices'],['ประเภทตราสาร','สกุลเงิน + ฐานตัน','ช่วงเวลา + ปริมาณ','เทียบเฉพาะราคาที่เข้ากันได้'],['world','registry','credits']);
add('world','system','How the world rail gets its numbers','ตัวเลขแถบโลกมาจากไหน','A feed’s observation date matters more than its refresh button.','วันที่สังเกตสำคัญกว่าปุ่มรีเฟรช',`NOAA atmospheric CO₂ is in ppm. NESO Great Britain grid intensity is in gCO₂/kWh and may be actual or forecast. RGGI auction and EU CBAM references are periodically published prices. The interface shows the observation date, fetch time, cadence and data tier; a dated fallback must remain labelled.

The global fossil-emission figure **38.1 GtCO₂ for 2025** is the Global Carbon Budget 2025 projection. It is not a second-by-second counter. The World Bank figures are annual-report context. None of these numbers supplies the Thai project calculator.

“Freshly fetched” does not mean “measured now”. If an upstream feed fails, a clearly marked snapshot is more honest than a fabricated live value. Follow the feed’s own source link to check the instrument and timestamp.`, `NOAA รายงาน CO₂ ในอากาศเป็น ppm ความเข้มการปล่อยโครงข่าย Great Britain ของ NESO เป็น gCO₂/kWh และอาจเป็นค่าจริงหรือพยากรณ์ RGGI และ EU CBAM เป็นราคาเผยแพร่เป็นรอบ หน้าจอแสดงวันที่สังเกต เวลาดึง ความถี่ และระดับข้อมูล fallback ที่มีวันที่ต้องมีป้ายกำกับ

ยอดฟอสซิลโลก **38.1 GtCO₂ สำหรับปี 2025** เป็นค่าคาดการณ์ Global Carbon Budget 2025 ไม่ใช่ตัวนับทุกวินาที ตัวเลข World Bank เป็นบริบทรายงานประจำปี ไม่มีค่าใดป้อนเครื่องคำนวณโครงการไทย

“เพิ่งดึงข้อมูล” ไม่ได้หมายถึง “เพิ่งวัด” หากต้นทางล้มเหลว snapshot ที่มีป้ายชัดตรงไปตรงมากว่าตัวเลขสดที่แต่งขึ้น เปิดลิงก์ต้นทางเพื่อตรวจประเภทและเวลา`,['noaa','neso','rggi','cbam','gcb','worldbank'],['Upstream observation','API fetch or labelled snapshot','Date / unit / cadence','Context only; no calculator input'],['ผลสังเกตต้นทาง','ดึง API หรือ snapshot มีป้าย','วันที่ / หน่วย / ความถี่','บริบทเท่านั้น ไม่ป้อนคำนวณ'],['markets','atmosphere','number-passport']);
add('standards','system','Standards: alignment without pretending certification','มาตรฐาน: อ้างแนวทางโดยไม่แอบอ้างรับรอง','Know what each standard covers and what this app can claim.','รู้ขอบเขตมาตรฐานและสิ่งที่ระบบอ้างได้',`**ISO 14064-1:2018** concerns organizational GHG quantification and reporting. **ISO 14064-2:2019** concerns project-level emission reductions/removal enhancements. **ISO 14064-3:2019** concerns validation and verification of GHG statements. **ISO 14067:2018** concerns product carbon footprints, which are different from an organization or a forest project.

This app’s traceable inputs, boundaries, equations and exports support preparation for review. Referencing these standards is a design alignment statement, not evidence of certification or complete clause-by-clause conformity. The full standards and the applicable TGO methodology govern the actual engagement.

No ISO certification, TGO endorsement, verification opinion or registry authorization is implied. When commissioning assurance, agree scope, criteria, materiality and evidence with the qualified reviewer.`, `**ISO 14064-1:2018** เกี่ยวกับการหาปริมาณและรายงานก๊าซเรือนกระจกองค์กร **ISO 14064-2:2019** เกี่ยวกับการลดการปล่อย/เพิ่มการดูดกลับระดับโครงการ **ISO 14064-3:2019** เกี่ยวกับการตรวจสอบความใช้ได้และทวนสอบถ้อยแถลง **ISO 14067:2018** เกี่ยวกับฟุตพริ้นท์ผลิตภัณฑ์ ซึ่งต่างจากองค์กรหรือโครงการป่า

ข้อมูลเข้า ขอบเขต สมการ และไฟล์ส่งออกที่ตรวจย้อนกลับได้ช่วยเตรียมงานสำหรับผู้ตรวจ การอ้างมาตรฐานเป็นคำอธิบายแนวทางออกแบบ ไม่ใช่หลักฐานรับรองหรือสอดคล้องทุกข้อ ต้องใช้มาตรฐานฉบับเต็มและระเบียบวิธี อบก. ที่เกี่ยวข้องกับงานจริง

ไม่สื่อว่ารับรอง ISO ได้รับ endorsement อบก. มีความเห็นทวนสอบ หรือมีอำนาจทะเบียน เมื่อตกลงงานตรวจให้กำหนดขอบเขต เกณฑ์ สาระสำคัญ และหลักฐานกับผู้ตรวจที่มีคุณสมบัติ`,['iso1','iso2','iso3','iso67','method'],['Organization → ISO 14064-1','Project → ISO 14064-2','Assurance → ISO 14064-3','Product → ISO 14067'],['องค์กร → ISO 14064-1','โครงการ → ISO 14064-2','การตรวจ → ISO 14064-3','ผลิตภัณฑ์ → ISO 14067'],['credits','footprint','exports']);
add('exports','system','Reproduce a result and hand it to a reviewer','ทำผลซ้ำและส่งต่อให้ผู้ตรวจ','Keep inputs, not just a screenshot of the answer.','เก็บข้อมูลเข้า ไม่ใช่แค่ภาพคำตอบ',`For the map, export JSON and CSV after selecting the area. For the project, export the assessment JSON alongside the table CSV. Keep original measurements, plot design, dates, source records and the boundary. The JSON contains the richer evidence trail; a table alone cannot replace it.

Uploaded boundaries and CSVs are processed browser-locally. This release does not provide durable cloud project storage. Export before closing or resetting. Language changes should preserve inputs; unit or factor changes invalidate stale derived results rather than silently reinterpret them.

To reproduce: use the same source versions and boundary, confirm units and factors, recalculate without rounding intermediate values, and compare the output and uncertainty assumptions. Record the deployment commit from /version.json. Do not substitute landscape totals for missing project observations.`, `แผนที่ให้ส่งออก JSON และ CSV หลังเลือกพื้นที่ โครงการให้เก็บ JSON การประเมินพร้อม CSV ตาราง เก็บผลวัดต้นฉบับ แบบสำรวจ วันที่ บันทึกแหล่งข้อมูล และขอบเขต JSON มีร่องรอยหลักฐานละเอียดกว่า ตารางอย่างเดียวแทนไม่ได้

ขอบเขตและ CSV ที่นำเข้าประมวลผลในเบราว์เซอร์ รุ่นนี้ไม่มีพื้นที่เก็บโครงการถาวรบนคลาวด์ ส่งออกก่อนปิดหรือเริ่มใหม่ เปลี่ยนภาษาควรรักษาข้อมูลเข้า ส่วนเปลี่ยนหน่วยหรือตัวคูณทำให้ผลอนุพันธ์เก่าหมดอายุ ไม่เปลี่ยนความหมายเงียบ ๆ

ทำซ้ำโดยใช้รุ่นข้อมูลและขอบเขตเดิม ตรวจหน่วยกับตัวคูณ คำนวณโดยไม่ปัดค่ากลาง แล้วเทียบผลและสมมติฐานความไม่แน่นอน บันทึก commit จาก /version.json อย่าเอายอดภูมิทัศน์แทนผลสังเกตโครงการที่ขาด`,['code','manifest','registry-data'],['Original evidence + boundary','Versioned inputs + calculation','JSON / CSV + commit','Independent reproduction'],['หลักฐานต้นฉบับ + ขอบเขต','ข้อมูลมีรุ่น + การคำนวณ','JSON / CSV + commit','ทำซ้ำโดยผู้ตรวจอิสระ'],['number-passport','project-change']);
add('sources','system','The source shelf','ชั้นวางแหล่งข้อมูล','All deployed dataset families, with dates and versions.','ทุกตระกูลข้อมูลที่ใช้ พร้อมวันที่และรุ่น',`The evidence shelf below lists every dataset in the deployed ledger manifest, plus the calculation methodology, national inventory comparison and public registry snapshot. Dataset links are evidence sources, not claims that their producers endorse this app.

RFD historical province forest-area records and data.go.th catalogues are context and discovery sources. They do not establish biomass for your project. Thailand BTR1 provides a national 2022 inventory; its land-use categories and accounting boundary are not interchangeable with satellite products.

For the deepest trace, open the manifest to inspect file hashes, retrieval dates, conversions, uncertainty and conservation. Consult the full research notebook for ingestion details and licence caveats. A new catalogue entry does not become an integrated layer until its data are retrieved, tested and wired into the app.`, `ชั้นหลักฐานด้านล่างแสดงทุกชุดข้อมูลใน manifest ที่ใช้อยู่ พร้อมระเบียบวิธี ไฟล์เทียบสำรวจระดับประเทศ และ snapshot ทะเบียน ลิงก์แหล่งข้อมูลไม่ใช่คำกล่าวว่าผู้ผลิตรับรองระบบนี้

พื้นที่ป่ารายจังหวัดย้อนหลังของกรมป่าไม้และ catalogue data.go.th ใช้เป็นบริบทและค้นหาแหล่งข้อมูล ไม่ได้ระบุมวลชีวภาพโครงการของคุณ BTR1 ไทยเป็นบัญชีประเทศปี 2022 หมวดใช้ที่ดินและขอบเขตบัญชีใช้แทนผลิตภัณฑ์ดาวเทียมไม่ได้

หากต้องการตรวจละเอียด เปิด manifest ดู hash วันที่ดึง ตัวแปลง ความไม่แน่นอน และการตรวจยอดรวม อ่านสมุดวิจัยฉบับเต็มสำหรับการนำเข้าและเงื่อนไขสิทธิ รายการใหม่ใน catalogue ยังไม่ใช่ชั้นข้อมูลที่เชื่อมแล้ว จนกว่าจะดึง ทดสอบ และต่อเข้าระบบจริง`,['cci','fnf','gfw','gfed','odiac','codab','climatetrace','btr1','nfi','method','registry-data','rfd','datagoth'],['Published source + licence','Retrieved version + hash','Tested ingestion','Labelled display + export'],['ต้นทางเผยแพร่ + สิทธิ','รุ่นที่ดึง + hash','นำเข้าและทดสอบ','แสดงผลมีป้าย + ส่งออก'],['number-passport','exports']);

